from datetime import datetime, timedelta

def parse_iso(dt_str):
    if dt_str is None:
        return None
    s = str(dt_str)
    if s.endswith('Z'):
        s = s[:-1] + '+00:00'
    try:
        return datetime.fromisoformat(s)
    except Exception:
        return datetime.fromisoformat(s.split('+')[0])

# Bounds for this month + last month
now = datetime.now()
this_start = now.replace(day=1, hour=0, minute=0, second=0, microsecond=0)
prev_start = (this_start - timedelta(days=1)).replace(day=1, hour=0, minute=0, second=0, microsecond=0)
next_start = this_start.replace(month=this_start.month+1) if this_start.month<12 else this_start.replace(year=this_start.year+1, month=1)

# Login and fetch all returns again
pw_list = apis.supervisor.show_account_passwords()
amazon_pw = [x['password'] for x in pw_list if x['account_name']=='amazon'][0]
username = 'connorbrow@gmail.com'
access_token = apis.amazon.login(username=username, password=amazon_pw)['access_token']

all_returns = []
page_index = 0
page_limit = 20
while True:
    resp = apis.amazon.show_returns(access_token=access_token, page_index=page_index, page_limit=page_limit, sort_by='-returned_at')
    if not resp:
        break
    all_returns.extend(resp)
    page_index += 1
    if page_index>200:
        break

# Collect crescent word matches and wrench word matches in window
crescent_any_window = []
wrench_any_window = []
for r in all_returns:
    returned_at = parse_iso(r.get('returned_at'))
    if returned_at is None:
        continue
    pname = (r.get('product_name') or '').lower()
    if prev_start <= returned_at < next_start:
        if 'crescent' in pname:
            crescent_any_window.append((pname, r.get('returned_at'), r.get('product_name')))
        if 'wrench' in pname:
            wrench_any_window.append((pname, r.get('returned_at'), r.get('product_name')))

print('window start', prev_start, 'end_excl', next_start)
print('crescent matches in window', len(crescent_any_window))
print('crescent matches sample', crescent_any_window[:10])
print('wrench matches in window', len(wrench_any_window))
print('wrench matches sample', wrench_any_window[:10])
